1	<!doctype html>
2	<html lang="en"><head><meta charset="utf-8"><title>FirstRun concept</title>
3	<script src="assets/gsap.min.js"></script>
4	<style>
5	@font-face{font-family:'Geist';src:url('assets/fonts/Geist.woff2') format('woff2');font-weight:100 900;font-style:normal}
6	@font-face{font-family:'Geist Mono';src:url('assets/fonts/GeistMono.woff2') format('woff2');font-weight:100 900;font-style:normal}
7	:root{--bg:#F5F5F7;--card:#FFFFFF;--ink:#1D1D1F;--muted:#6E6E73;--line:#D8D8DE;--soft:#EBEBF0;--pass:#1F8A3B;--fail:#D70015;--accent:#0066CC;--accent-soft:#E8F1FC;--pass-soft:#E7F4EA;--fail-soft:#FBE6E8;
8	--shadow:0 1px 2px rgba(29,29,31,.05),0 24px 60px -20px rgba(29,29,31,.18)}
9	*{box-sizing:border-box;margin:0;padding:0}
10	html,body{width:1920px;height:1080px;overflow:hidden;background:var(--bg);color:var(--ink);font-family:'Geist','Inter',sans-serif;-webkit-font-smoothing:antialiased}
11	#root{position:relative;width:1920px;height:1080px;overflow:hidden;background:var(--bg)}
12	#bg{position:absolute;inset:0;background:radial-gradient(ellipse 70% 60% at 50% 42%,#FFFFFF 0%,rgba(255,255,255,0) 70%)}
13	.mono{font-family:'Geist Mono','JetBrains Mono',monospace}
14	.scene{position:absolute;inset:0;opacity:0}
15	.content{width:100%;height:100%;padding:110px 160px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:40px;box-sizing:border-box}
16	.h1{font-weight:700;font-size:84px;line-height:1.05;letter-spacing:-.045em;text-align:center}
17	.h1 .w{display:inline-block}
18	.sub{font-weight:400;font-size:42px;line-height:1.2;letter-spacing:-.02em;color:var(--muted);text-align:center}
19	.card{background:var(--card);border:1px solid rgba(29,29,31,.07);border-radius:28px;box-shadow:var(--shadow)}
20	/* icons */
21	.ic{width:34px;height:34px;flex:none}
22	.ic circle{fill:var(--pass)}
23	.ic path{stroke:#fff;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round}
24	.ic.bad circle{fill:var(--fail)}
25	.ic.fix circle{fill:var(--accent)}
26	.ic.pend circle{fill:none;stroke:#C7C7CC;stroke-width:2}
27	.ic.run circle{fill:none;stroke:var(--soft);stroke-width:3}
28	.ic.run path{stroke:var(--accent);stroke-width:3}
29	/* terminal */
30	.term{width:1200px;padding:0 0 30px}
31	.term .bar{display:flex;align-items:center;gap:10px;padding:22px 30px;border-bottom:1px solid var(--soft)}
32	.term .bar i{width:14px;height:14px;border-radius:50%;display:block}
33	.term .bar .t{margin-left:16px;font-size:20px;color:var(--muted)}
34	.tl{display:flex;align-items:center;gap:20px;padding:14px 44px 0;font-size:30px}
35	.tl .cmd{flex:1;color:var(--ink)}
36	.tl .cmd b{color:var(--muted);font-weight:400}
37	.tl .st{display:flex;align-items:center;gap:12px;font-size:24px;color:var(--pass);font-weight:500}
38	.tl .st.bad{color:var(--fail)}
39	.tl.err{font-size:24px;color:var(--fail);padding-top:6px}
40	.chips{display:flex;gap:20px}
41	.chip{display:flex;align-items:center;gap:12px;padding:14px 26px;border-radius:999px;background:var(--card);border:1px solid rgba(29,29,31,.07);box-shadow:0 1px 2px rgba(29,29,31,.05);font-size:26px;font-weight:500}
42	.chip .ic{width:26px;height:26px}
43	.chip span{color:var(--muted);font-weight:400}
44	/* s2 track */
45	.track{position:relative;width:1300px;height:250px}
46	.track .ln{position:absolute;left:48px;right:48px;top:48px;height:4px;background:var(--line);border-radius:2px}
47	.node{position:absolute;top:0;width:96px;height:96px;border-radius:50%;background:var(--card);border:3px solid var(--line);display:flex;align-items:center;justify-content:center;font-size:34px;font-weight:600;color:var(--muted)}
48	.node .fill{position:absolute;inset:-3px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff;font-size:40px;opacity:0}
49	.node.n1 .fill,.node.n2 .fill{background:var(--pass)}
50	.node.n3 .fill{background:var(--fail)}
51	.node .lab{position:absolute;top:116px;font-size:22px;color:var(--muted);white-space:nowrap;font-weight:500}
52	.dev{position:absolute;top:-92px;left:14px;display:flex;flex-direction:column;align-items:center;gap:8px}
53	.dev .tag{font-size:22px;font-weight:600;color:var(--accent);background:var(--accent-soft);padding:6px 16px;border-radius:999px;white-space:nowrap}
54	.dev .dot{width:24px;height:24px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 6px rgba(0,102,204,.18)}
55	.never{position:absolute;top:180px;left:780px;width:520px;display:flex;flex-direction:column;align-items:center;gap:10px}
56	.never .br{width:100%;height:16px;border:3px solid #C7C7CC;border-top:none;border-radius:0 0 14px 14px}
57	.never .t{font-size:26px;color:var(--muted);font-weight:500}
58	/* wordmark */
59	.wm{font-family:'Geist Mono','JetBrains Mono',monospace;font-weight:600;letter-spacing:-.04em;display:flex;align-items:center;gap:.06em}
60	.wm .cur{display:inline-block;width:.52em;height:.86em;background:var(--accent);border-radius:.04em}
61	/* s4 */
62	.cmdpill{display:flex;align-items:center;gap:18px;padding:24px 40px;border-radius:999px;font-size:34px}
63	.cmdpill .p{color:var(--accent);font-weight:600}
64	.typed{display:inline-block;overflow:hidden;white-space:nowrap;vertical-align:bottom}
65	.caret{display:inline-block;width:3px;height:40px;background:var(--ink);margin-left:2px}
66	.box{width:1240px;padding:30px 40px 36px;border:2px dashed #C7C7CC;border-radius:30px;background:rgba(255,255,255,.55)}
67	.box .hd{display:flex;align-items:center;gap:14px;margin-bottom:22px}
68	.box .hd .k{font-size:24px;font-weight:600;background:var(--ink);color:#fff;padding:6px 18px;border-radius:999px}
69	.box .hd .m{font-size:22px;color:var(--muted)}
70	.grid6{display:grid;grid-template-columns:1fr 1fr;gap:14px 24px}
71	.row{display:flex;align-items:center;gap:18px;padding:16px 22px;background:var(--card);border-radius:18px;border:1px solid rgba(29,29,31,.06);font-size:24px}
72	.row .n{color:var(--muted);width:30px;font-weight:600}
73	.row .c{flex:1}
74	.row .ic{width:30px;height:30px;position:relative}
75	.stk{position:relative;width:30px;height:30px;flex:none}
76	.stk .ic{position:absolute;inset:0}
77	/* s5 */
78	.bfp{display:flex;gap:56px;font-size:128px;font-weight:700;letter-spacing:-.05em}
79	.bfp .b{color:var(--fail)}.bfp .f{color:var(--accent)}.bfp .p{color:var(--pass)}
80	.out{width:1320px;padding:28px 0 30px}
81	.ol{display:flex;align-items:center;gap:22px;padding:12px 44px;font-size:28px}
82	.ol .k{width:150px;font-weight:600}
83	.ol.l1 .k{color:var(--fail)}.ol.l2 .k{color:var(--accent)}.ol.l3 .k{color:var(--pass)}
84	.ol .v{color:var(--ink)}
85	.ol .v b{color:var(--muted);font-weight:400}
86	.pr{width:1320px;display:flex;align-items:center;gap:28px;padding:28px 40px}
87	.pr .pi{width:68px;height:68px;border-radius:50%;background:var(--pass);display:flex;align-items:center;justify-content:center;flex:none}
88	.pr .tx{flex:1;display:flex;flex-direction:column;gap:8px}
89	.pr .tt{font-size:32px;font-weight:600;letter-spacing:-.02em}
90	.pr .mt{font-size:22px;color:var(--muted)}
91	.pr .open{font-size:22px;font-weight:600;color:#fff;background:var(--pass);padding:8px 20px;border-radius:999px}
92	.pr .df{font-size:24px;font-weight:600}
93	.pr .df .a{color:var(--pass)}.pr .df .d{color:var(--fail)}
94	/* s6 */
95	.tools{display:flex;gap:40px}
96	.tool{width:540px;height:560px;padding:44px;display:flex;flex-direction:column;gap:22px}
97	.tool .top{display:flex;align-items:center;gap:22px}
98	.logo{width:84px;height:84px;border-radius:20px;display:block;flex:none}
99	.logo.chipw{background:#fff;border:1.5px solid var(--line);padding:14px}
100	.tool .nm{font-size:50px;font-weight:700;letter-spacing:-.035em}
101	.tool .rl{font-size:34px;line-height:1.2;color:var(--ink);font-weight:600;letter-spacing:-.025em}
102	.tool .rl b{color:var(--ink);font-weight:600}
103	.viz{flex:1;border-radius:20px;background:var(--bg);padding:26px 24px;position:relative;overflow:hidden;display:flex;flex-direction:column;justify-content:center}
104	.span{display:flex;align-items:center;gap:12px;height:30px;margin:6px 0}
105	.span .sl{width:104px;font-size:20px;color:var(--muted)}
106	.span .tr{flex:1;position:relative;height:20px}
107	.span .sb{position:absolute;top:0;height:20px;border-radius:5px;background:var(--accent);transform-origin:left center}
108	.span.r .sb{background:#9CC0EA}.span.f .sb{background:var(--fail)}.span.v .sb{background:var(--pass)}
109	.cm{position:absolute;left:40px;right:70px;top:152px;height:4px;background:var(--line);border-radius:2px}
110	.cd{position:absolute;top:137px;width:34px;height:34px;border-radius:50%;background:var(--pass);border:4px solid var(--bg)}
111	.cd.last{background:var(--accent)}
112	.clab{position:absolute;top:190px;font-size:20px;color:var(--muted);font-weight:500;white-space:nowrap}
113	.sess{position:absolute;top:78px;font-size:20px;font-weight:600;color:var(--accent);background:var(--accent-soft);padding:6px 14px;border-radius:999px;white-space:nowrap}
114	.cfo{display:flex;align-items:flex-end;gap:18px;height:100%}
115	.cfo .cp{align-self:center;font-size:20px;font-weight:600;background:var(--card);border:1px solid var(--line);padding:10px 14px;border-radius:14px;white-space:nowrap}
116	.cfo .ar{align-self:center;font-size:28px;color:var(--muted)}
117	.bars{flex:1;display:flex;align-items:flex-end;gap:10px;height:190px;position:relative}
118	.bars i{flex:1;background:var(--ink);border-radius:6px 6px 2px 2px;transform-origin:bottom center;display:block}
119	.bars i.hi{background:var(--pass)}
120	.bars .bl{position:absolute;left:0;top:-6px;font-size:20px;color:var(--muted);font-weight:500}
121	/* s7 */
122	.tagline{font-size:88px;font-weight:700;letter-spacing:-.05em}
123	.tagline .lit{color:var(--accent)}
124	.built{position:absolute;left:0;right:0;bottom:96px;display:flex;flex-direction:column;align-items:center;gap:22px}
125	.built .row1{display:flex;align-items:center;gap:30px;font-size:28px;color:var(--muted)}
126	.built .lg{display:flex;align-items:center;gap:14px;color:var(--ink);font-weight:600}
127	.built .lg .logo{width:52px;height:52px;border-radius:13px}
128	.built .lg .logo.chipw{padding:9px}
129	.built .url{font-size:26px;color:var(--muted)}
130	</style></head><body>
131	<div id="root" data-composition-id="firstrun-concept" data-start="0" data-duration="41" data-width="1920" data-height="1080">
132	<div id="bg"></div>
133	
134	<!-- S1 0.0 to 4.9 : the break nobody saw -->
135	<div class="scene" id="s1"><div class="content">
136	  <div class="h1" id="s1h"><span class="w">Your</span> <span class="w">quickstart</span> <span class="w">broke</span> <span class="w">last</span> <span class="w">Tuesday.</span></div>
137	  <div class="sub" id="s1s">Nobody on your team noticed.</div>
138	  <div class="card term mono" id="s1t">
139	    <div class="bar"><i style="background:#FF5F57"></i><i style="background:#FEBC2E"></i><i style="background:#28C840"></i><span class="t">~/acme-quickstart</span></div>
140	    <div class="tl" id="s1l1"><span class="cmd"><b>$</b> pip install acme</span><span class="st"><svg class="ic" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11"/><path d="M7 12.5l3.2 3.2L17 9"/></svg>step 1/6</span></div>
141	    <div class="tl" id="s1l2"><span class="cmd"><b>$</b> acme init my-app</span><span class="st"><svg class="ic" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11"/><path d="M7 12.5l3.2 3.2L17 9"/></svg>step 2/6</span></div>
142	    <div class="tl" id="s1l3"><span class="cmd"><b>$</b> acme run --demo</span><span class="st bad"><svg class="ic bad" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11"/><path d="M8.5 8.5l7 7M15.5 8.5l-7 7"/></svg>step 3/6</span></div>
143	    <div class="tl err" id="s1l4">Error: module 'acme.demo' not found</div>
144	  </div>
145	  <div class="chips" id="s1c">
146	    <div class="chip"><svg class="ic" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11"/><path d="M7 12.5l3.2 3.2L17 9"/></svg>CI <span>passing</span></div>
147	    <div class="chip"><svg class="ic" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11"/><path d="M7 12.5l3.2 3.2L17 9"/></svg>Docs <span>published</span></div>
148	    <div class="chip"><svg class="ic" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11"/><path d="M7 12.5l3.2 3.2L17 9"/></svg>Status <span>all green</span></div>
149	  </div>
150	</div></div>
151	
152	<!-- S2 4.4 to 9.1 : a new developer found it -->
153	<div class="scene" id="s2"><div class="content" style="gap:56px">
154	  <div class="h1" id="s2h">A new developer did, at step 3.</div>
155	  <div class="sub" id="s2s">Then they left.</div>
156	  <div class="track" id="s2tr" style="margin-top:70px">
157	    <div class="ln"></div>
158	    <div class="node n1" style="left:0"><span class="num">1</span><div class="fill">&#10003;</div><span class="lab">install</span></div>
159	    <div class="node n2" style="left:240.8px"><span class="num">2</span><div class="fill">&#10003;</div><span class="lab">init</span></div>
160	    <div class="node n3" style="left:481.6px"><span class="num">3</span><div class="fill">&#10005;</div><span class="lab">run demo</span></div>
161	    <div class="node" style="left:722.4px"><span>4</span><span class="lab">open app</span></div>
162	    <div class="node" style="left:963.2px"><span>5</span><span class="lab">deploy</span></div>
163	    <div class="node" style="left:1204px"><span>6</span><span class="lab">done</span></div>
164	    <div class="dev" id="s2dev"><span class="tag">new developer</span><span class="dot"></span></div>
165	    <div class="never" id="s2nv"><div class="br"></div><div class="t">Steps 4 to 6: never seen</div></div>
166	  </div>
167	</div></div>
168	
169	<!-- S3 8.6 to 10.9 : meet FirstRun -->
170	<div class="scene" id="s3"><div class="content" style="gap:36px">
171	  <div class="wm" id="s3wm" style="font-size:190px"><span>FirstRun</span><span class="cur" id="s3cur"></span></div>
172	  <div class="sub" id="s3s" style="font-size:38px">Your quickstart, run by an agent before your users run it.</div>
173	</div></div>
174	
175	<!-- S4 10.4 to 17.3 : it runs every step in a clean container -->
176	<div class="scene" id="s4"><div class="content" style="gap:36px">
177	  <div class="h1" id="s4h">Give it a docs URL.</div>
178	  <div class="card cmdpill mono" id="s4p"><span class="p">$</span><span class="typed" id="s4ty">firstrun run https://docs.acme.dev/quickstart</span><span class="caret" id="s4ca"></span></div>
179	  <div class="sub" id="s4s" style="font-size:40px">It runs every step in a clean container, like a brand-new developer.</div>
180	  <div class="box" id="s4b">
181	    <div class="hd"><span class="k mono">clean container</span><span class="m mono">fresh image · no cache · no saved state</span></div>
182	    <div class="grid6 mono">
183	      <div class="row"><span class="n">1</span><span class="c">pip install acme</span><div class="stk"><svg class="ic pend" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/></svg><svg class="ic" id="s4o1" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11"/><path d="M7 12.5l3.2 3.2L17 9"/></svg></div></div>
184	      <div class="row"><span class="n">4</span><span class="c">open localhost:3000</span><div class="stk"><svg class="ic pend" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/></svg></div></div>
185	      <div class="row"><span class="n">2</span><span class="c">acme init my-app</span><div class="stk"><svg class="ic pend" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/></svg><svg class="ic" id="s4o2" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11"/><path d="M7 12.5l3.2 3.2L17 9"/></svg></div></div>
186	      <div class="row"><span class="n">5</span><span class="c">acme deploy --dry-run</span><div class="stk"><svg class="ic pend" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/></svg></div></div>
187	      <div class="row"><span class="n">3</span><span class="c">acme run --demo</span><div class="stk"><svg class="ic pend" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/></svg><svg class="ic run" id="s4o3" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M12 2a10 10 0 0 1 10 10"/></svg></div></div>
188	      <div class="row"><span class="n">6</span><span class="c">acme status</span><div class="stk"><svg class="ic pend" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/></svg></div></div>
189	    </div>
190	  </div>
191	</div></div>
192	
193	<!-- S5 16.8 to 25.9 : break, fix, prove, PR -->
194	<div class="scene" id="s5"><div class="content" style="gap:40px">
195	  <div class="bfp"><span class="b" id="s5b">Break.</span><span class="f" id="s5f">Fix.</span><span class="p" id="s5p">Prove.</span></div>
196	  <div class="card out mono" id="s5o">
197	    <div class="ol l1" id="s5l1"><svg class="ic bad" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11"/><path d="M8.5 8.5l7 7M15.5 8.5l-7 7"/></svg><span class="k">step 3/6</span><span class="v">acme run --demo <b>→</b> module 'acme.demo' not found</span></div>
198	    <div class="ol l2" id="s5l2"><svg class="ic fix" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11"/><path d="M7 12.5l3.2 3.2L17 9"/></svg><span class="k">fixed</span><span class="v">docs bug <b>→</b> step 1 was missing acme[demo]</span></div>
199	    <div class="ol l3" id="s5l3"><svg class="ic" viewBox="0 0 24 24"><circle cx="12" cy="12" r="11"/><path d="M7 12.5l3.2 3.2L17 9"/></svg><span class="k">verified</span><span class="v">second clean container <b>→</b> 6/6 steps pass</span></div>
